function fresh(){return {cp:0,floor:0,lives:5,nextLife:0,party:[],captainId:null,ownedIds:[],xpById:{},training:{force:0,vitality:0,ward:0},rpg:freshRpg(),summons:0,gold:0,attack:1,defense:1,best:0,tokens:0,protection:0,passives:{},mercy:0,firstRoom:true,dustPaid:[],defeatBag:[],lastDefeat:null,rivalBag:[],lastRival:null,trialBag:[],safeBag:[],lastRoom:null}}
function loadProgress(){const base=fresh();try{const p=JSON.parse(localStorage.getItem('tower-progress-v1')||'null');if(p&&p.schema===1){for(const k of ['cp','best','summons','gold','tokens'])if(Number.isSafeInteger(p[k])&&p[k]>=0)base[k]=p[k];for(const k of ['favor','mercy','grace','vessel','strength','guard'])if(p.passives?.[k]===true)base.passives[k]=true;for(const id of ['force','vitality','ward'])base.training[id]=trainingRank(p.training,id);for(const c of roster){const xp=p.xpById?.[c.id];if(Number.isSafeInteger(xp)&&xp>=0&&xp<=1000000000)base.xpById[c.id]=xp;}if(roster.some(c=>c.id===p.captainId))base.captainId=p.captainId;const old=Array.isArray(p.roster)?p.roster:[];base.ownedIds=roster.filter(c=>old.includes(c.id)||(Array.isArray(p.ownedIds)&&p.ownedIds.includes(c.id))||c.id===base.captainId).map(c=>c.id);const active=[...new Set([base.captainId,...old].filter(id=>base.ownedIds.includes(id)))].slice(0,2+[18,56,110].filter(f=>base.cp>=f).length);base.rpg=loadRpg(p.rpg,base.xpById,base.ownedIds,base.best);base.party=active.map(id=>memberFor(roster.find(c=>c.id===id),base.xpById,base.training,base.rpg));}}catch(e){}return base}
function saveProgress(){if(preview)return;try{localStorage.setItem('tower-progress-v1',JSON.stringify({schema:1,captainId:state.captainId,ownedIds:state.ownedIds,xpById:state.xpById,training:state.training,rpg:state.rpg,cp:state.cp,best:state.best,summons:state.summons,gold:state.gold,tokens:state.tokens,passives:state.passives,roster:state.party.map(c=>c.id)}))}catch(e){console.warn('Local progress could not be saved',e)}}
function levelInfo(xp=0){xp=Math.max(0,Math.floor(xp));const level=Math.floor((1+Math.sqrt(1+8*xp/100))/2);return {level,current:xp-50*(level-1)*level,required:100*level};}
function freshRpg(){return {levels:{},items:{},equipped:{}};}
function gearById(id){return GEAR.find(g=>g.id===id);}
function xpForLevel(level){return 50*(level-1)*level;}
function xpStatus(id,xps,rpg){const xp=Math.max(0,Math.floor(xps[id]||0)),level=Math.max(1,Math.min(levelInfo(xp).level,Math.floor(rpg?.levels?.[id]||1))),required=100*level,current=Math.max(0,xp-xpForLevel(level));return {level,current:Math.min(current,required),required,ready:current>=required,banked:Math.max(0,current-required),cost:100*level};}
function currentLevel(id){return xpStatus(id,state.xpById,state.rpg);}
function itemRank(rpg,id){return Math.max(0,Math.min(10,Math.floor(rpg?.items?.[id]||0)));}
function unlockMilestoneGear(rpg,best){const fresh=[];for(const g of GEAR){if(g.gift&&best>=g.floor&&!itemRank(rpg,g.id)){rpg.items[g.id]=1;fresh.push(g);}}return fresh;}
function loadRpg(raw,xps,owned,best){const r=freshRpg();for(const c of roster){const max=levelInfo(xps[c.id]||0).level;const v=raw?.levels?.[c.id];r.levels[c.id]=Number.isSafeInteger(v)?Math.min(max,Math.max(1,v)):raw?1:max;}for(const g of GEAR){const rank=raw?.items?.[g.id];if(Number.isInteger(rank)&&rank>=1&&rank<=10)r.items[g.id]=rank;}unlockMilestoneGear(r,best);const used=new Set();for(const id of owned){const eq={};const prior=Object.values(raw?.equipped?.[id]||{}).filter(item=>typeof item==='string'&&gearById(item)&&itemRank(r,item)&&r.levels[id]>=gearById(item).level).sort((a,b)=>gearScore(b,r)-gearScore(a,r));for(const item of prior){const g=gearById(item);if(!used.has(item)&&!eq[g.slot]){eq[g.slot]=item;used.add(item);}}r.equipped[id]=eq;}return r;}
function gearBonus(id,rpg){const total={hp:0,str:0,def:0};for(const slot of GEAR_SLOTS){const item=rpg?.equipped?.[id]?.[slot],g=gearById(item),rank=itemRank(rpg,item);if(!g||!rank)continue;for(const stat of ['hp','str','def'])total[stat]+=(g[stat]||0)*(1+.2*(rank-1));}return total;}
function gearOwner(rpg,id){return Object.keys(rpg.equipped).find(c=>Object.values(rpg.equipped[c]||{}).includes(id))||null;}

function refreshMember(id){const i=state.party.findIndex(c=>c.id===id);if(i<0)return;const c=state.party[i],base=roster.find(r=>r.id===id),grown=memberFor(base,state.xpById,state.training,state.rpg),ratio=c.hp>0?c.current/c.hp:0;Object.assign(c,grown,{current:Math.max(0,Math.min(grown.hp,grown.hp*ratio))});updateHP(c,i);const u=$('unit-'+i);if(u){const tag=u.querySelector('.tag span');if(tag)tag.textContent=memberLabel(c);drawEquipment(u,c);}}
function canLevelNow(){return !preview&&(phase==='camp'||(phase==='doors'&&!locked)||(phase==='reward'&&pendingReward?.credited===true));}
