function smithCost(rank){return 250000*rank*rank;}
function relicUpgradePlan(rpg,ids,gold){const candidates=[...new Set(ids.flatMap(id=>Object.values(rpg.equipped[id]||{})))].filter(id=>itemRank(rpg,id)>0&&itemRank(rpg,id)<10);const ranks=Object.fromEntries(candidates.map(id=>[id,itemRank(rpg,id)])),changes={};let spent=0,count=0;while(true){const id=candidates.filter(id=>ranks[id]<10&&smithCost(ranks[id])<=gold-spent).sort((a,b)=>ranks[a]-ranks[b]||gearScore(b,rpg)-gearScore(a,rpg))[0];if(!id)break;spent+=smithCost(ranks[id]);ranks[id]++;changes[id]=ranks[id];count++;}return {spent,count,changes};}
