function trainingCap(id){return id==='ward'?60:100;}
function trainingRank(training,id){const v=training?.[id];return Number.isInteger(v)?Math.max(0,Math.min(trainingCap(id),v)):0;}
function trainingCost(rank){return 2+Math.floor(rank/4);}
function wardMultiplier(training){return 1/(1+.025*trainingRank(training,'ward'));}
function memberFor(c,xps={},training={},rpg=freshRpg()){const lv=xpStatus(c.id,xps,rpg).level,base=towerBase(c.power),growth=1+.02*(lv-1),gear=gearBonus(c.id,rpg);const maxHP=base*growth*(1+.05*trainingRank(training,'vitality'))*(1+gear.hp);return {...c,hp:maxHP,str:base*growth*(1+.05*trainingRank(training,'force'))*(1+gear.str),def:defenseBase(c.power)*growth*(1+.025*trainingRank(training,'ward'))*(1+gear.def),current:maxHP};}
function characterDefense(c){return 100/(100+Math.max(0,c.def||0));}
function encounterStats(floor,boss=false,strength=false){const f=Math.max(1,Math.floor(floor));const max=strength?(115+18*f)*(1+f/90+f*f/40000):boss?(430+22*f)*(1+f/55+f*f/18000):(150+12*f)*(1+f/75+f*f/30000);const hit=(8+1.2*f)*(1+Math.sqrt(f)/18)*(boss?1.6:1);return {hp:Math.round(max),hit};}
function difficultyName(f){return f<=5?'Initiate':f<=18?'Veteran':f<=56?'Elite':f<=110?'Master':f<=243?'Mythic':'Ascendant';}
function trainParty(id){if(phase!=='camp'||!['force','vitality','ward'].includes(id))return false;const rank=trainingRank(state.training,id),cost=trainingCost(rank);if(rank>=trainingCap(id)||state.tokens<cost)return false;state.tokens-=cost;state.training[id]=rank+1;state.party.forEach((c,i)=>{const base=roster.find(r=>r.id===c.id);if(!base)return;const grown=memberFor(base,state.xpById,state.training,state.rpg),delta=grown.hp-c.hp;c.hp=grown.hp;c.str=grown.str;c.def=grown.def;if(c.current>0)c.current=Math.min(c.hp,c.current+Math.max(0,delta));updateHP(c,i);});saveProgress();hud();return true;}
function captainAttackMultiplier(){return 1+(currentLevel(state.captainId).level-1)*.01;}
function memberLabel(c){return (c.id===state.captainId?'♛ ':'')+c.name+' · Lv '+currentLevel(c.id).level;}
function awardPartyXP(n){const ready=[];state.party.forEach(c=>{const was=currentLevel(c.id).ready;state.xpById[c.id]=Math.min(1000000000,(state.xpById[c.id]||0)+n);if(!was&&currentLevel(c.id).ready)ready.push(c.name+' ready to level up');});return ready;}
function fillPartySlots(){if(preview)return;for(const id of state.ownedIds){if(state.party.length>=slots())break;if(state.party.some(c=>c.id===id))continue;const c=roster.find(r=>r.id===id);if(c)state.party.push(memberFor(c,state.xpById,state.training,state.rpg));}}
function chooseStartingParty(captain,companion){if(phase!=='select'||captain===companion)return;const a=roster.find(c=>c.id===captain),b=roster.find(c=>c.id===companion);if(!a||!b)return;const hasProgress=state.best>0||state.cp>0||state.tokens>0||state.summons>0||state.gold>0||state.ownedIds.length>1;state.ownedIds=[...new Set([captain,companion,...(hasProgress?state.ownedIds:[])])];state.captainId=captain;state.party=[memberFor(a,state.xpById,state.training,state.rpg),memberFor(b,state.xpById,state.training,state.rpg)];saveProgress();newRun();}
