function partyCardState(c,i){const lv=currentLevel(c.id),ratio=clamp(c.hp>0?c.current/c.hp:0,0,1),eq=state.rpg.equipped[c.id]||{},weapon=gearById(eq.weapon);return {lv,ratio,weapon:weapon?.name||'No weapon',protected:c.current>0&&state.protection>0,down:c.current<=0,acting:!!$('unit-'+i)?.classList.contains('turnActing'),canLevel:lv.ready&&canLevelNow(),safe:canLevelNow()};}
