// Build 08: separate facing from body translation and UI; artwork stays intact.
function faceUnit(u, direction){if(!u)return;u.dataset.facing=direction<0?'left':'right';u.style.setProperty('--face',direction<0?'-1':'1');}
function walkTo(u, targetX, targetY, scale=1, delay=0, duration=null){
 if(!u)return 0;
 const start={x:Number(u.dataset.moveX||0),y:Number(u.dataset.moveY||0),scale:Number(u.dataset.moveScale||1)};
 const baseX=u.offsetLeft+u.offsetWidth/2, baseY=u.offsetTop+u.offsetHeight;
 const end={x:targetX-baseX,y:targetY-baseY,scale};
 const dx=end.x-start.x,dy=end.y-start.y,dist=Math.hypot(dx,dy);
 const ms=reduced?0:(duration??Math.round(clamp(dist/Math.max(230,scene.clientWidth*.72)*1000,360,860)));
 const tf=p=>`translate(${p.x}px,${p.y}px) scale(${p.scale})`;
 if(Math.abs(dx)>3)faceUnit(u,dx<0?-1:1);
 const apply=()=>{if(!u.isConnected)return;u.style.transform=tf(end);u.dataset.moveX=end.x;u.dataset.moveY=end.y;u.dataset.moveScale=end.scale;u.classList.remove('walking');};
 if(!ms){apply();return 0;}
 later(()=>{if(!u.isConnected)return;u.classList.add('walking');let a=u.animate([{transform:tf(start)},{transform:tf(end)}],{duration:ms,easing:'linear',fill:'forwards'});later(()=>{apply();a.cancel()},ms);},delay);
 return delay+ms;
}
